import { useState } from 'react';
import {
  JxSegmentedControl,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'serif' | 'mono' | 'rounded';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  denseLayout: boolean;
  font: Font;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const fontLabels: Record<Font, string> = {
  system: 'Системный',
  serif: 'С засечками',
  mono: 'Моноширинный',
  rounded: 'Скруглённый',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [denseLayout, setDenseLayout] = useState(false);
  const [font, setFont] = useState<Font>('system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    onChange?.({ theme, scale, denseLayout, font, ...next });
  };

  return (
    <div className="jx-stack jx-stack-lg" style={{ maxWidth: 480 }}>
      <div className="jx-inline jx-inline-between jx-inline-center">
        <h2 className="jx-heading jx-heading-md">Внешний вид</h2>
        <JxBadge variant="neutral">{themeLabels[theme]}</JxBadge>
      </div>

      <div className="jx-stack jx-stack-sm">
        <label className="jx-label">Тема</label>
        <JxSegmentedControl
          value={theme}
          onValueChange={(value) => {
            const next = value as Theme;
            setTheme(next);
            emit({ theme: next });
          }}
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
        />
      </div>

      <div className="jx-stack jx-stack-sm">
        <div className="jx-inline jx-inline-between jx-inline-center">
          <label className="jx-label">Масштаб интерфейса</label>
          <span className="jx-text jx-text-muted">{scale}%</span>
        </div>
        <JxSlider
          min={80}
          max={140}
          step={5}
          value={scale}
          onValueChange={(value) => {
            setScale(value);
            emit({ scale: value });
          }}
        />
      </div>

      <div className="jx-inline jx-inline-between jx-inline-center">
        <div className="jx-stack jx-stack-xs">
          <span className="jx-label">Плотная вёрстка</span>
          <span className="jx-text jx-text-sm jx-text-muted">
            Меньше отступов между элементами
          </span>
        </div>
        <JxSwitch
          value={denseLayout}
          onValueChange={(value) => {
            setDenseLayout(value);
            emit({ denseLayout: value });
          }}
        />
      </div>

      <JxDivider />

      <div className="jx-stack jx-stack-sm">
        <h3 className="jx-heading jx-heading-sm">Ещё</h3>
        <div className="jx-stack jx-stack-sm">
          <label className="jx-label">Шрифт</label>
          <JxSelect
            value={font}
            onValueChange={(value) => {
              const next = value as Font;
              setFont(next);
              emit({ font: next });
            }}
            items={(Object.keys(fontLabels) as Font[]).map((key) => ({
              value: key,
              label: fontLabels[key],
            }))}
          />
        </div>
      </div>
    </div>
  );
}

